#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int graph[4][2] = {{1, 2}, {0, 3}, {0, 3}, {1, 2}};
    int seen[4] = {0};
    int queue[4];
    int head = 0, tail = 0;
    queue[tail++] = 0;
    seen[0] = 1;
    while (head < tail) {
        int current = queue[head++];
        for (int i = 0; i < 2; i++) {
            int next = graph[current][i];
            if (!seen[next]) {
                seen[next] = 1;
                queue[tail++] = next;
            }
        }
    }
    for (int i = 0; i < tail; i++) {
        if (i > 0) printf(" ");
        printf("%d", queue[i]);
    }
    printf("\n");
    return 0;
}

#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<std::vector<int>> graph = {{1, 2}, {0, 3}, {0, 3}, {1, 2}};
    std::vector<bool> seen(graph.size(), false);
    std::vector<int> queue = {0};
    seen[0] = true;
    int head = 0;
    while (head < static_cast<int>(queue.size())) {
        int current = queue[head++];
        for (int next : graph[current]) {
            if (!seen[next]) {
                seen[next] = true;
                queue.push_back(next);
            }
        }
    }
    for (int i = 0; i < static_cast<int>(queue.size()); i++) {
        if (i > 0) std::cout << " ";
        std::cout << queue[i];
    }
    std::cout << "\n";
    return 0;
}

using System;
using System.Collections.Generic;

int[][] graph = {
    new int[] {1, 2}, new int[] {0, 3},
    new int[] {0, 3}, new int[] {1, 2}
};
bool[] seen = new bool[graph.Length];
List<int> queue = new List<int> {0};
seen[0] = true;
int head = 0;
while (head < queue.Count) {
    int current = queue[head++];
    foreach (int next in graph[current]) {
